private void scanFrom(File file,ClassLoader classloader) throws IOException {
  if (!file.exists()) {
    return;
  }
  if (file.isDirectory()) {
    scanDirectory(classloader,file);
  }
 else {
    try {
      scanJar(file,classloader);
    } catch (RuntimeException e) {
      // Handle or log the runtime exception
      e.printStackTrace();
    }
  }
}
